// Besichtigungsvorgang anlegen – verarbeitet alle eingehenden Wünsche.
return $input.all().map(({ json }) => {
  const b = json.body ?? json;
  return { json: { kontaktId: b.kontaktId, objektId: b.objektId, investorEmail: b.investorEmail,
                   wunsch: b.wunsch ?? '', verkaeuferEmail: b.verkaeuferEmail ?? '', teamKuerzel: b.teamKuerzel ?? '',
                   angelegt: new Date().toISOString() } };
});

// Kalendereintrag nach Titelkonvention des Standardprozesses – nur Struktur.
return $input.all().map(({ json }) => {
  const b = json.body ?? json;
  const titel = `BES mit ${b.teamKuerzel || json.teamKuerzel || '<Kürzel>'} und ${b.investorName ?? b.investorTelefon ?? json.investorEmail ?? '<Investor>'}`;
  return { json: { ...json, kalender: { titel, ort: b.objektAdresse ?? '', beginn: b.termin ?? null,
                                        teilnehmer: [b.teamEmail].filter(Boolean) } } };
});
